from AlgorithmImports import *


class IndependentDailyStrategies(QCAlgorithm):
    RSI_THRESHOLD = 70

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_closes = {}
        self.aapl_red_streak = 0
        self.spy_sma_values = RollingWindow[float](2)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        self.UpdateMarketState(data)

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.spy not in self.previous_closes or self.aapl not in self.previous_closes:
            return

        if self.spy_sma_values.Count < 2:
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        previous_spy_close = self.previous_closes[self.spy]
        previous_spy_sma = self.spy_sma_values[1]
        current_spy_sma = float(self.spy_sma.Current.Value)

        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma
            and float(spy_bar.Close) < current_spy_sma
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and float(self.aapl_rsi.Current.Value) > self.RSI_THRESHOLD:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma
            and float(spy_bar.Close) > current_spy_sma
        )

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(
                float(self.Portfolio.TotalPortfolioValue) * 0.40 / float(spy_bar.Close)
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / float(aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def UpdateMarketState(self, data: Slice):
        for symbol, bar in data.Bars.items():
            current_close = float(bar.Close)
            previous_close = self.previous_closes.get(symbol)

            if symbol == self.aapl:
                if previous_close is not None and current_close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            if symbol == self.spy and self.spy_sma.IsReady:
                self.spy_sma_values.Add(float(self.spy_sma.Current.Value))

            self.previous_closes[symbol] = current_close
